window.docContents[165].resolve({"/Elementary-Functions/___4___26-Integrals/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___26-Integrals--___4___26_LPAR_iii_RPAR_-Definite-integrals":{"contents":"For positive integer frequencies, E9 and E10 are the sine and cosine\northogonality integrals on [0,π]; E11 gives both square integrals as π/2.\nE12 is the conditionally convergent Dirichlet limit\n∫₀^∞ sin(mt)/t dt, with values π/2, 0, and -π/2 for positive, zero,\nand negative integer m.  E13 is the pair of Fresnel limits\n∫₀^∞ sin(t²)dt = ∫₀^∞ cos(t²)dt = ½√(π/2) = √(π/8).  These are improper\nlimits, not Lebesgue integrals over Ioi; the formal statements use Tendsto\nof finite interval integrals.  DLMF cites Copson (1935) for E12–E13.\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.26 Integrals","header":"4.26.2. §4.26(iii) Definite integrals","id":"/Elementary-Functions/___4___26-Integrals/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___26-Integrals--___4___26_LPAR_iii_RPAR_-Definite-integrals"}});